import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useCaseSummary = () => {
  const [{ caseSummaryData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const caseSummaryRequest = useCallback((payload = {}) => {
    callApi(actions.getCaseSummary({ query: payload }))
  }, [callApi])
  return { caseSummaryData, caseSummaryRequest }
}

