export const useAddMarketing = () => {
  const [{ addMarketingData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const addMarketingRequest = (payload = {}) => {
    callApi(actions.addMarketing({ body: payload }))
  }
  return { addMarketingData, addMarketingRequest }
}
