/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import { Alert, Col, Form, Input, message, Modal, Row, Select, Spin } from 'antd'
import { useLeadConfig } from '../../../../state/hooks'
import { useAddMarketing } from '../../../../state/CaseSummary/hooks/useCaseSummary'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import lodash from 'lodash'

const FORM_FIELDS = {
  NAME: 'name',
  EMAIL: 'email',
  CHANNEL: 'channel'
}

const AddMarketing = ({ form, onCancel }) => {
  const { getFieldDecorator } = form
  const { leadConfigData, leadConfigRequest } = useLeadConfig()
  const { addMarketingRequest } = useAddMarketing()
  const { resetError } = useResetError()
  const [{ ADD_MARKETING_LOADER }] = useLoaderContextValue()
  const [{ ADD_MARKETING_ERROR, addMarketingErrorData, addMarketingStatus }] = useErrorContextValue()

  const handleSubmit = () => {
    form.validateFields((error, values) => {
      if (!error) {
        addMarketingRequest(lodash.pickBy(values))
      }
    })
  }

  useEffect(() => {
    if (ADD_MARKETING_ERROR && addMarketingErrorData) {
      const { error } = addMarketingErrorData
      const values = form.getFieldsValue()
      form.setFieldsValue()
      for (const key in error) {
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [addMarketingErrorData])
  useEffect(() => {
    if (addMarketingStatus === 'success') {
      message.success('Marketing added successfully')
      resetError([
        'addMarketingStatus'
      ])
      onCancel()
    }
  }, [addMarketingStatus])

  useEffect(() => {
    leadConfigRequest()
  }, [])
  return (
    <Modal
      visible
      title='Add Marketing'
      onCancel={onCancel}
      onOk={handleSubmit}
      okText='Submit'
    >
      <Spin spinning={!!ADD_MARKETING_LOADER}>
        {ADD_MARKETING_ERROR && (!addMarketingErrorData) && <Alert type='error' message={addMarketingStatus} banner />}
        <Row>
          <Col>
            <Form.Item
              hasFeedback
              label='Name'
              required
            >
              {
                getFieldDecorator(FORM_FIELDS.NAME, {
                  rules: [
                    {
                      required: true,
                      message: 'Marketing name is required.'
                    }
                  ]
                })(
                  <Input />
                )
              }
            </Form.Item>
          </Col>
          <Col>
            <Form.Item
              hasFeedback
              label='Email'
            >
              {
                getFieldDecorator(FORM_FIELDS.EMAIL, {
                  validateTrigger: ['onBlur'],
                  rules: [
                    {
                      type: 'email',
                      message: 'Please enter a valid email address'
                    }
                  ]
                })(
                  <Input type='email' />
                )
              }
            </Form.Item>
          </Col>
          <Col>
            <Form.Item
              hasFeedback
              label='Channel'
            >
              {
                getFieldDecorator(FORM_FIELDS.CHANNEL, {
                  rules: [
                    {
                      required: true,
                      message: 'Channel is required'
                    }
                  ]
                })(
                  <Select style={{ width: '100%' }}>
                    {
                      leadConfigData && leadConfigData.channels && leadConfigData.channels.map(({ name, code }) => (
                        <Select.Option value={code} key={code}>{name}</Select.Option>
                      ))
                    }
                  </Select>
                )
              }
            </Form.Item>
          </Col>
        </Row>
      </Spin>
    </Modal>
  )
}
export default Form.create({ name: 'add-marketing' })(AddMarketing)
