import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {

  MARKETING_SUMMARY_REQUEST: 'MARKETING_SUMMARY_REQUEST',
  MARKETING_SUMMARY: 'MARKETING_SUMMARY',
  CASE_SUMMARY_REQUEST: 'CASE_SUMMARY_REQUEST',
  CASE_SUMMARY: 'CASE_SUMMARY',
  ADD_MARKETING_REQUEST: 'ADD_MARKETING_REQUEST',
  ADD_MARKETING: 'ADD_MARKETING',

  getMarketingSummary: (payload) => ({
    type: actions.MARKETING_SUMMARY_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getMarketingSummary
    }
  }),
  getCaseSummary: payload => ({
    type: actions.CASE_SUMMARY_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getCaseSummary
    }
  }),
  addMarketing: payload => ({
    type: actions.ADD_MARKETING_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addMarketing
    }

  })
}

export default actions
