import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Alert, Button, Col, Icon, Row, Spin, Table } from 'antd'
import { useEffect, useState } from 'react'
import { RowWithMargin, EbSectionWrapper } from '../../../CommonComponents/index'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { ColTextAlignRight } from '../../../CommonComponents/index.style'
import { useCaseSummary, useMarketingSummary } from '../../../state/CaseSummary/hooks/useCaseSummary'
import { useLeadConfig } from '../../../state/hooks'
import AddMarketingForm from './components/addMarketingForm'
import CaseSummaryFilters from './components/filters'
import Sumamry from './components/summary'
import { summaryColumns } from './utility'
import ExportExcel from '../../../components/ExportExcel'
import ebUrls from '../../../../../../request/urls/employeeBenefit'

const CaseSummary = () => {
  const { marketingSummaryData, marketingSummaryRequest } = useMarketingSummary()
  const { caseSummaryData, caseSummaryRequest } = useCaseSummary()
  const { leadConfigRequest, leadConfigData } = useLeadConfig()
  const [{ MARKETING_SUMMARY_LOADER }] = useLoaderContextValue()
  const [{ CASE_SUMMARY_ERROR, caseSummaryStatus, MARKETING_SUMMARY_ERROR, marketingSummaryStatus }] = useErrorContextValue()
  const [addMarketingVisible, toggleAddMarketingVisiblility] = useState(false)
  const [listMetaData, setListMetaData] = useState({})
  const [filters, setFilters] = useState()

  const handleTableChange = (params) => {
    const query = {
      page: params.current,
      per_page: params.pageSize
    }
    marketingSummaryRequest({ ...query, ...filters })
  }

  useEffect(() => {
    if (marketingSummaryData && marketingSummaryData.meta_data) {
      setListMetaData(marketingSummaryData.meta_data)
    }
  }, [marketingSummaryData])

  useEffect(() => {
    marketingSummaryRequest({ ...filters })
    caseSummaryRequest({ ...filters })
    leadConfigRequest()
  }, [marketingSummaryRequest, leadConfigRequest, caseSummaryRequest, filters])

  return (
    <>

      <EbSectionWrapper>
        {CASE_SUMMARY_ERROR && <div className='mb-5'><Alert type='error' message={`Could not load case summary. ${caseSummaryStatus}`} banner /></div>}
        {MARKETING_SUMMARY_ERROR && <div className='mb-5'><Alert type='error' message={`Could not marketing summary. ${marketingSummaryStatus}`} banner /></div>}
        <Row gutter={16} className='mb-5'>
          <Col span={12}><h2>Case Summary</h2></Col>
          <ColTextAlignRight span={12}>
            <PermissionCheckerV2 requiredPermission='ops.eb_create_marketing'>
              <Button
                type='primary'
                onClick={() => toggleAddMarketingVisiblility(true)}
              >
                Add Marketing <Icon type='plus' />
              </Button>
            </PermissionCheckerV2>
          </ColTextAlignRight>
        </Row>
        <CaseSummaryFilters onFilter={setFilters} />
      </EbSectionWrapper>
      <Sumamry data={caseSummaryData && caseSummaryData.data} filtersApplied={!!filters} />
      <EbSectionWrapper>
        <RowWithMargin>
          <ColTextAlignRight>
            <ExportExcel url={ebUrls.exportCaseSummary} queryParams={filters} disabled={!marketingSummaryData?.data?.length} />
          </ColTextAlignRight>
        </RowWithMargin>
        <Spin spinning={!!MARKETING_SUMMARY_LOADER}>
          <Table
            columns={summaryColumns({ leadConfigData })}
            bordered
            dataSource={marketingSummaryData ? marketingSummaryData.data : []}
            onChange={handleTableChange}
            pagination={{
              pageSize: listMetaData.page_size,
              total: listMetaData.total_records,
              current: listMetaData.page
            }}
            scroll={{ x: true }}
          />
        </Spin>
      </EbSectionWrapper>
      {
        addMarketingVisible && <AddMarketingForm onCancel={() => toggleAddMarketingVisiblility(false)} />
      }
    </>
  )
}
export default CaseSummary
