import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Row, Col, Form, Select, DatePicker, Button, Icon, Input, Spin } from 'antd'
import { useEffect } from 'react'
import { RowWithMargin } from '../../../../CommonComponents'
import { useCaseSummary, useMarketingSummary } from '../../../../state/CaseSummary/hooks/useCaseSummary'
import { useLeadConfig } from '../../../../state/hooks'
const { Option } = Select
const { RangePicker } = DatePicker
const { Item } = Form

const formItemLayout = {
  labelCol: {
    xs: { span: 24 },
    sm: { span: 8 }
  },
  wrapperCol: {
    xs: { span: 24 },
    sm: { span: 16 }
  }
}

const CaseSummaryFilters = ({ form, onFilter }) => {
  const { leadConfigData, leadConfigRequest } = useLeadConfig()
  const { caseSummaryRequest } = useCaseSummary()
  const { marketingSummaryRequest } = useMarketingSummary()
  const [{ CASE_SUMMARY_LOADER, MARKETING_SUMMARY_LOADER }] = useLoaderContextValue()
  const { getFieldDecorator } = form
  const handleResetFilter = () => {
    onFilter(undefined)
    form.resetFields()
    caseSummaryRequest()
    marketingSummaryRequest()
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        const toBeSentValues = {
          marketing: values.marketing,
          channel: values.channels,
          updated_at_start_date: Array.isArray(values.date_range) && values.date_range.length === 2 ? values.date_range[0].format('YYYY-MM-DD') : undefined,
          updated_at_end_date: Array.isArray(values.date_range) && values.date_range.length === 2 ? values.date_range[1].format('YYYY-MM-DD') : undefined
        }
        onFilter(toBeSentValues)
        caseSummaryRequest(toBeSentValues)
        marketingSummaryRequest(toBeSentValues)
      }
    })
  }

  useEffect(() => {
    leadConfigRequest()
  }, [leadConfigRequest])
  return (
    <Form
      {...formItemLayout}
      onSubmit={handleSubmit}
    >
      <Spin spinning={!!MARKETING_SUMMARY_LOADER || !!CASE_SUMMARY_LOADER}>
        <RowWithMargin>
          <Col span={24}>
            <Row gutter={16}>
              <Col span={8}>
                <Item
                  label='Date Range' labelAlign='left'
                >
                  {
                    getFieldDecorator('date_range', {})(
                      <RangePicker allowClear />
                    )
                  }
                </Item>
              </Col>
              <Col span={8}>
                <Item
                  label='Marketing'
                  labelAlign='left'
                >
                  {
                    getFieldDecorator('marketing', {})(
                      <Input placeholder='Pingkan' allowClear />
                    )
                  }
                </Item>
              </Col>
              <Col span={8}>
                <Item
                  label='Channel' labelAlign='left'
                >
                  {getFieldDecorator('channels', {})(
                    <Select allowClear>
                      {
                        leadConfigData && leadConfigData.channels && leadConfigData.channels.map(({ code, name }) => (
                          <Option value={code} key={code}>{name}</Option>
                        ))
                      }
                    </Select>
                  )}
                </Item>
              </Col>
            </Row>
            <Row gutter={16} type='flex' justify='center'>
              <Col span={3}>
                <Button
                  type='danger'
                  onClick={handleResetFilter}
                >
                  Clear Filter
                  <Icon type='delete' />
                </Button>
              </Col>
              <Col span={3}>
                <Button
                  type='primary'
                  htmlType='submit'
                >
                  Apply Filter
                  <Icon type='filter' />
                </Button>
              </Col>
            </Row>
          </Col>
        </RowWithMargin>
      </Spin>
    </Form>
  )
}
export default Form.create({ name: 'case-summary-filters' })(CaseSummaryFilters)
