import React from 'react'
import { Row, Col, Spin, Empty } from 'antd'
import { EbSectionWrapper, RowWithMargin } from '../../../../CommonComponents'
import SummaryTable from './summaryTable'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'

const Sumamry = ({ data, filtersApplied }) => {
  const orderedData = [
    { heading: 'PROSPECT', data: data?.PROSPECT },
    { heading: 'CLOSING', data: data?.CLOSING },
    { heading: 'FOLLOW UP', data: data?.FOLLOW_UP },
    { heading: 'LOSING', data: data?.LOSING },
    { heading: 'HOT', data: data?.HOT },
    { heading: 'TOTAL', data: data?.TOTAL }
  ]

  const [{ CASE_SUMMARY_LOADER }] = useLoaderContextValue()
  return (
    <EbSectionWrapper>
      <Spin spinning={!!CASE_SUMMARY_LOADER}>
        <h2>Summary</h2>
        <Row gutter={40}>
          {
            data
            // TODO: verify if data do not comes as empty object
              ? orderedData.map(({ heading, data }, index) => (
                <React.Fragment key={heading}>
                  <Col span={12}>
                    <SummaryTable
                      heading={heading}
                      // TODO: use useMemo for evaluating heading.
                      count={data?.count} // TODO: .saftey operator
                      premium={data?.premium}
                    />
                  </Col>
                  {index % 2 !== 0 && <RowWithMargin />}
                </React.Fragment>
                ))
              : <Empty />
          }
        </Row>
      </Spin>
    </EbSectionWrapper>
  )
}
export default Sumamry
